@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#111714;--lime:#d8ff58;--paper:#f0f2e9;--muted:#a9b0a7;--glass:rgba(13,20,17,.78)}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#151b17;color:var(--paper);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#a9bba5}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,15,12,.54),transparent 25%,transparent 68%,rgba(7,13,11,.48)),radial-gradient(ellipse at center,transparent 45%,rgba(5,10,8,.35) 100%)}.topbar{position:absolute;top:0;left:0;right:0;height:76px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.13);background:linear-gradient(180deg,rgba(9,15,12,.52),transparent);z-index:2}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none;font-size:12px;font-weight:700;letter-spacing:1.55px;line-height:1.15}.brand b{color:var(--lime)}.brand small{display:block;color:#bbc4b9;font-size:8px;letter-spacing:2.2px;margin-top:5px;font-weight:600}.brand-mark{width:37px;height:37px;border:1px solid rgba(216,255,88,.75);color:var(--lime);font:800 27px 'Barlow Condensed';display:grid;place-items:center;transform:skew(-6deg)}.top-center{font-size:10px;font-weight:700;letter-spacing:2px;color:#e3e7dd}.top-center i{color:var(--lime);font-style:normal;padding:0 8px}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 10px var(--lime);margin-right:8px}.icon-button{border:1px solid rgba(255,255,255,.24);background:rgba(255,255,255,.07);padding:9px 12px;font-size:13px;cursor:pointer}.icon-button span{font-size:9px;letter-spacing:1.2px;margin-left:6px}.mission-card{position:absolute;top:103px;left:36px;width:292px;padding:19px 20px 16px;background:var(--glass);border:1px solid rgba(255,255,255,.16);border-left:2px solid var(--lime);backdrop-filter:blur(12px);box-shadow:0 12px 40px #10151033}.mission-label{font-size:9px;font-weight:700;letter-spacing:1.7px;color:var(--lime)}.tiny-star{font-size:14px;vertical-align:-1px;margin-right:5px}.job-tag{float:right;color:#919c90;font-size:9px}.mission-card h1{font:800 23px 'Barlow Condensed',sans-serif;letter-spacing:.7px;margin:9px 0 2px}.mission-card p{color:#b4beb2;margin:0;font-size:11px}.mission-progress{display:flex;align-items:center;gap:9px;margin:17px 0 14px;font-size:9px;color:#bbc2b8}.progress-track{height:3px;background:#465047;flex:1}.progress-track i{height:100%;display:block;width:0;background:var(--lime);transition:width .5s}.objective-row{border-top:1px solid rgba(255,255,255,.14);padding-top:12px;display:flex;align-items:center;font-size:10px;font-weight:600}.objective-icon{font-size:17px;color:var(--lime);margin-right:9px}.distance{margin-left:auto;color:var(--lime);font-size:9px;letter-spacing:.5px}.status-card{position:absolute;right:36px;top:103px;width:168px;padding:16px;background:var(--glass);border:1px solid rgba(255,255,255,.15);backdrop-filter:blur(12px)}.cash-label,.heat-head,.vehicle-data>span{font-size:8px;color:#aab4a9;letter-spacing:1.5px;font-weight:700}.cash-value{font:700 29px 'Barlow Condensed';letter-spacing:.3px;margin-top:2px}.cash-value:first-letter{color:var(--lime)}.status-divider{height:1px;background:#ffffff20;margin:12px 0}.heat-head{display:flex;justify-content:space-between}.heat-head span:last-child{color:var(--lime);letter-spacing:1px}.heat-stars{display:flex;gap:4px;margin-top:6px;color:#536052;font-size:13px}.heat-stars i{font-style:normal}.heat-caption{font-size:9px;color:#a4aea2;margin-top:6px}.minimap-frame{position:absolute;right:35px;bottom:37px;width:184px;height:210px;padding:2px;background:rgba(10,17,14,.77);border:1px solid rgba(255,255,255,.25);backdrop-filter:blur(5px)}#minimap{width:180px;height:180px;display:block}.map-label{font-size:8px;letter-spacing:1.6px;color:#c5cec2;padding:6px 6px 0;display:flex;justify-content:space-between}.map-label span{color:var(--lime)}.vehicle-hud{position:absolute;right:237px;bottom:42px;width:160px;padding:9px 12px;display:none;align-items:center;gap:11px;background:var(--glass);border:1px solid #ffffff27}.vehicle-hud.active{display:flex}.speed-wrap{display:flex;align-items:baseline;gap:3px}.speed-number{font:700 31px 'Barlow Condensed';color:white}.speed-unit{font-size:7px;letter-spacing:1px;color:#aab4a8}.vehicle-data{flex:1;min-width:0}.vehicle-data>span{display:block;font-size:7px}.vehicle-data b{display:block;font-size:9px;margin:3px 0 5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fuel-track{height:2px;background:#596253}.fuel-track i{width:86%;height:100%;display:block;background:var(--lime)}.controls-hint{position:absolute;bottom:42px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:13px;padding:9px 14px;background:rgba(12,18,15,.72);border:1px solid #ffffff22;font-size:8px;letter-spacing:1px;color:#d4dbd0;white-space:nowrap}.controls-hint>i{height:13px;width:1px;background:#ffffff33}kbd{font:700 9px 'DM Sans';min-width:18px;height:18px;padding:0 4px;display:inline-grid;place-items:center;margin-right:2px;background:#ffffff17;border:1px solid #ffffff30;color:#fff;border-radius:2px}.toast{position:absolute;left:50%;top:30%;transform:translate(-50%,-10px);padding:12px 20px;background:#101813dc;border:1px solid #d8ff5870;color:#e9f2dc;font-size:11px;letter-spacing:.3px;opacity:0;transition:.3s;pointer-events:none;z-index:4}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;inset:0;z-index:3;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(7,13,10,.75),rgba(7,13,10,.18) 72%,rgba(7,13,10,.15));transition:opacity .55s,visibility .55s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-panel{width:min(580px,80vw);margin-left:-17%;padding-top:34px}.intro-kicker{font-size:9px;letter-spacing:2.6px;font-weight:700;color:#dce4d9}.intro-kicker span{display:inline-block;width:20px;height:1px;background:var(--lime);vertical-align:middle;margin-right:9px}.intro-title{font:900 clamp(60px,8.5vw,110px)/.79 'Barlow Condensed',sans-serif;letter-spacing:-1px;margin:24px 0 22px;color:#f5f6ef;text-shadow:0 3px 25px #0005}.intro-title em{font-style:normal;color:var(--lime)}.title-dot{color:var(--lime)}.intro-description{max-width:330px;font-size:12px;line-height:1.7;color:#d0d6cb;margin:0 0 25px}.start-button{border:0;background:var(--lime);color:#182014;padding:15px 19px;font-size:10px;font-weight:800;letter-spacing:1.2px;cursor:pointer;min-width:202px;text-align:left;transition:transform .2s,background .2s}.start-button:hover{transform:translateY(-2px);background:#e5ff86}.start-button span{float:right;font-size:15px;line-height:10px}.intro-foot{display:flex;gap:19px;margin-top:34px;font-size:7px;color:#aab4a9;letter-spacing:1.5px}.intro-foot span+span{border-left:1px solid #ffffff44;padding-left:17px}.overlay-note{position:absolute;right:38px;bottom:35px;font-size:8px;letter-spacing:1.4px;color:#f0f3e8}.overlay-note span{color:#b4beb2}.pause-badge{display:none;position:absolute;inset:0;z-index:5;align-items:center;justify-content:center;flex-direction:column;background:#0b100da9;backdrop-filter:blur(4px)}.pause-badge.active{display:flex}.pause-badge b{font:800 42px 'Barlow Condensed';letter-spacing:4px;color:var(--lime)}.pause-badge span{font-size:11px;color:#dce3d8;margin-top:8px}.mobile-controls{display:none}
@media(max-width:700px){.topbar{height:61px;padding:0 16px}.brand{font-size:10px;gap:8px}.brand-mark{width:31px;height:31px;font-size:23px}.brand small{font-size:6px}.top-center{font-size:8px;letter-spacing:1px}.icon-button{padding:7px}.icon-button span{display:none}.mission-card{top:76px;left:13px;width:min(255px,68vw);padding:13px}.mission-card h1{font-size:20px}.mission-card p{font-size:10px}.status-card{top:76px;right:13px;width:112px;padding:11px}.cash-value{font-size:23px}.heat-stars{font-size:11px}.heat-caption{font-size:8px}.minimap-frame{right:12px;bottom:15px;transform:scale(.8);transform-origin:bottom right}.vehicle-hud{right:155px;bottom:27px;width:140px;padding:7px}.controls-hint{display:none}.intro-panel{margin-left:0;width:82vw}.intro-title{font-size:clamp(58px,15vw,86px)}.intro-description{max-width:280px}.overlay-note{right:15px;bottom:14px;font-size:7px}.intro-foot{gap:9px;font-size:6px}.intro-foot span+span{padding-left:9px}.mobile-controls{display:none;position:absolute;inset:auto 0 18px 0;justify-content:space-between;align-items:end;padding:0 18px;pointer-events:none}.mobile-controls.active{display:flex}.dpad,.mobile-actions{pointer-events:auto}.dpad button,.mobile-actions button{width:43px;height:43px;border:1px solid #ffffff60;background:#101813aa;color:white;backdrop-filter:blur(4px);border-radius:50%;font-weight:700;touch-action:none}.dpad>div{display:flex;gap:4px}.dpad>button{margin:0 auto 4px;display:block}.dpad button:active,.mobile-actions button:active{background:#d8ff58;color:#121811}.mobile-actions{display:flex;gap:9px}.mobile-actions button{font-size:14px}.mobile-actions small{font-size:6px;letter-spacing:.5px}.toast{top:42%}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const $ = id => document.getElementById(id);
  const WORLD = { w: 2600, h: 1900 }, roadW = 112, blockW = 300, stride = blockW + roadW;
  let W = 0, H = 0, dpr = 1, started = false, paused = false, inCar = false, car = null, cash = 2450, step = 0, heat = 0, muted = false, last = 0, toastTimer = 0;
  const keys = Object.create(null), camera = {x: 0, y: 0};
  const player = {x: 620, y: 610, angle: -Math.PI / 2, speed: 0, walk: 0};
  const destinations = [{x: 1120,y: 395,label:'PACKAGE PICKUP',name:'Market Street'}, {x:1900,y:1240,label:'FIRST DROP',name:'Marina Vista'}, {x:520,y:1510,label:'FINAL DELIVERY',name:'Old Town'}];
  const blocks = [], trees = [], traffic = [], parked = [];
  const palette = ['#d5c6a9','#c9d0c0','#d3c9b5','#b8c5b6','#d9d4c6','#b9c9c4','#d4c4ae'];
  function resize(){dpr=Math.min(window.devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}
  window.addEventListener('resize',resize); resize();
  // Procedural city grid: wide boulevards, shaded sidewalks, parks, buildings and palms.
  for(let y=0,ri=0;y<WORLD.h;y+=stride,ri++) for(let x=0,ci=0;x<WORLD.w;x+=stride,ci++){
    const bx=x+roadW+10, by=y+roadW+10, bw=Math.min(blockW-20,WORLD.w-bx-9), bh=Math.min(blockW-20,WORLD.h-by-9);
    if(bw<60||bh<60)continue;
    const park=((ci*13+ri*7)%11===2)||((ci===4&&ri===2));
    const lot={x:bx,y:by,w:bw,h:bh,park, buildings:[]};
    if(!park){let seed=(ci*19+ri*31+9)%100, count=seed>76?1:seed>45?2:3;for(let n=0;n<count;n++){
      const cols=count===1?1:2, rows=Math.ceil(count/cols), cw=(bw-27-(cols-1)*11)/cols, ch=(bh-27-(rows-1)*12)/rows;
      const xx=bx+13+(n%cols)*(cw+11), yy=by+13+Math.floor(n/cols)*(ch+12), inset=(n*7+seed)%13;
      lot.buildings.push({x:xx+inset,y:yy+inset,w:Math.max(52,cw-inset*1.5),h:Math.max(54,ch-inset*1.4),color:palette[(seed+n*3)%palette.length],hue:(seed+n*17)%40});
    }} else {for(let n=0;n<15;n++)trees.push({x:bx+18+((n*73+ri*19)%Math.max(30,bw-36)),y:by+22+((n*49+ci*21)%Math.max(30,bh-42)),r:9+(n%3)*2});}
    blocks.push(lot);
  }
  function isRoad(x,y){let rx=((x%stride)+stride)%stride, ry=((y%stride)+stride)%stride;return rx<roadW||ry<roadW}
  // Find clear road parking positions.
  for(let i=0;i<18;i++) {let x=235+(i*197)%2200, y=182+(i*283)%1600;if(isRoad(x,y)&&Math.random()>.35)parked.push({x,y,angle:((i%2)?0:Math.PI/2),color:['#bd6648','#d1d1c5','#457e83','#c4a34d','#4e5960'][i%5],name:['Vesper Coupe','Cobalt Sedan','Sunliner','Mesa Classic','Harbor Compact'][i%5],occupied:false});}
  for(let i=0;i<12;i++)traffic.push({x:150+(i*223)%2300,y:166+(i*191)%1650,axis:i%2?'x':'y',dir:i%3===0?-1:1,speed:30+(i*7)%25,color:['#758376','#a76f58','#d0b886','#6a7b86'][i%4],phase:i*3});
  function screen(x,y){return{x:x-camera.x,y:y-camera.y}}
  function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function drawGround(){
    ctx.fillStyle='#9bb49a';ctx.fillRect(0,0,W,H);
    // grassy lots and paved plazas
    for(const b of blocks){let p=screen(b.x,b.y);if(p.x>W+350||p.y>H+350||p.x+b.w<-350||p.y+b.h<-350)continue;
      if(b.park){ctx.fillStyle='#739578';ctx.fillRect(p.x,p.y,b.w,b.h);ctx.fillStyle='#b9b89d';ctx.fillRect(p.x+b.w*.45,p.y,8,b.h);ctx.fillRect(p.x,p.y+b.h*.55,b.w,7);for(let n=0;n<5;n++){ctx.fillStyle='#d8d1b3';ctx.fillRect(p.x+18+n*37,p.y+b.h*.35,20,3)}}
      else{ctx.fillStyle='#b6ae98';ctx.fillRect(p.x,p.y,b.w,b.h);ctx.fillStyle='#c8c0ab';ctx.fillRect(p.x+4,p.y+4,b.w-8,b.h-8);}
    }
    // Roads span the entire map; markings are drawn in world-space for stable camera motion.
    ctx.fillStyle='#555c59';ctx.fillRect(-camera.x,-camera.y,WORLD.w,WORLD.h);
    // road surfaces as repeated broad streets
    for(let x=0;x<WORLD.w;x+=stride){let sx=x-camera.x;ctx.fillStyle='#555d5b';ctx.fillRect(sx,-camera.y,roadW,WORLD.h);ctx.fillStyle='#858b7e';ctx.fillRect(sx+roadW-5,-camera.y,5,WORLD.h);ctx.fillStyle='#777f75';ctx.fillRect(sx+roadW,-camera.y,8,WORLD.h)}
    for(let y=0;y<WORLD.h;y+=stride){let sy=y-camera.y;ctx.fillStyle='#555d5b';ctx.fillRect(-camera.x,sy,WORLD.w,roadW);ctx.fillStyle='#858b7e';ctx.fillRect(-camera.x,sy+roadW-5,WORLD.w,5);ctx.fillStyle='#777f75';ctx.fillRect(-camera.x,sy+roadW,WORLD.w,8)}
    // broken center lines and crosswalks
    ctx.fillStyle='#d7cf9f';for(let x=0;x<WORLD.w;x+=stride)for(let y=0;y<WORLD.h;y+=40){let sx=x+roadW/2-camera.x,sy=y+roadW/2-camera.y;ctx.fillRect(sx-1,sy,2,15);ctx.fillRect(sx-1,sy-10,2,15)}
    ctx.fillStyle='#d8d7c6';for(let x=0;x<WORLD.w;x+=stride)for(let y=0;y<WORLD.h;y+=stride){let sx=x-camera.x,sy=y-camera.y;for(let k=0;k<6;k++){ctx.fillRect(sx+6+k*7,sy+roadW-16,4,9);ctx.fillRect(sx+roadW-16,sy+6+k*7,9,4)}}
    // Avenue planted medians
    ctx.fillStyle='#839679';for(let x=0;x<WORLD.w;x+=stride*3){let sx=x+roadW-2-camera.x;ctx.fillRect(sx,-camera.y,5,WORLD.h)}
  }
  function drawBuildings(){
    for(const lot of blocks){if(lot.park)continue;for(const b of lot.buildings){let p=screen(b.x,b.y),x=p.x,y=p.y;if(x>W+350||y>H+350||x+b.w<-350||y+b.h<-350)continue;
      // soft cast shadow and raised side give a miniature, dimensional city feel
      ctx.fillStyle='rgba(25,34,27,.24)';rounded(x+8,y+12,b.w,b.h,3);
      ctx.fillStyle='#aaa894';ctx.fillRect(x+5,y+7,b.w,b.h);
      ctx.fillStyle=b.color;rounded(x,y,b.w,b.h,2);
      ctx.fillStyle='rgba(255,255,255,.19)';ctx.fillRect(x+4,y+4,b.w-8,4);
      ctx.fillStyle='rgba(83,100,86,.23)';ctx.fillRect(x+6,y+11,b.w-12,3);
      // rooftop facade detail, roof machinery and skylights
      const cols=Math.max(2,Math.floor(b.w/24));for(let c=0;c<cols;c++){const wx=x+10+c*((b.w-20)/cols);ctx.fillStyle=(c%3===0)?'#68766d':'#859184';ctx.fillRect(wx,y+17,8,Math.min(7,b.h*.1));}
      if(b.w>65&&b.h>75){ctx.fillStyle='#b4b8a5';ctx.fillRect(x+b.w*.58,y+b.h*.53,b.w*.25,b.h*.25);ctx.fillStyle='rgba(68,91,84,.34)';ctx.fillRect(x+b.w*.61,y+b.h*.56,b.w*.19,b.h*.19)}
      ctx.fillStyle='rgba(54,73,63,.22)';ctx.fillRect(x+8,y+b.h-11,b.w-16,5);
    }}
    for(const t of trees){const p=screen(t.x,t.y);if(p.x<-30||p.x>W+30||p.y<-30||p.y>H+30)continue;ctx.fillStyle='rgba(32,47,37,.28)';ctx.beginPath();ctx.ellipse(p.x+3,p.y+5,t.r*1.2,t.r*.72,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#675f48';ctx.fillRect(p.x-2,p.y-2,4,9);ctx.fillStyle='#416d4d';ctx.beginPath();ctx.arc(p.x,p.y,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#62875c';ctx.beginPath();ctx.arc(p.x-3,p.y-4,t.r*.6,0,Math.PI*2);ctx.fill()}
    // street lamps and small shop awnings on sidewalks
    for(let x=roadW;x<WORLD.w;x+=stride)for(let y=roadW;y<WORLD.h;y+=stride){let p=screen(x+9,y+roadW-12);ctx.fillStyle='#414b43';ctx.fillRect(p.x,p.y,2,11);ctx.fillStyle='#f0dfa2';ctx.beginPath();ctx.arc(p.x+1,p.y,3,0,Math.PI*2);ctx.fill()}
  }
  function drawCar(x,y,angle,color,isPlayer=false){const p=screen(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(angle);ctx.fillStyle='rgba(15,21,17,.4)';rounded(-16,-7,36,19,6);ctx.fillStyle='#252b29';rounded(-17,-9,34,18,5);ctx.fillStyle=color;rounded(-15,-8,30,15,4);ctx.fillStyle='rgba(199,223,213,.78)';rounded(-5,-6,12,11,3);ctx.fillStyle='rgba(35,52,53,.84)';ctx.fillRect(-3,-5,8,9);ctx.fillStyle='#f5e5ad';ctx.fillRect(12,-5,2,3);ctx.fillRect(12,2,2,3);ctx.fillStyle='#a94c3e';ctx.fillRect(-15,-5,2,3);ctx.fillRect(-15,2,2,3);if(isPlayer){ctx.strokeStyle='#e7ff88';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,20,12,0,0,Math.PI*2);ctx.stroke()}ctx.restore()}
  function drawWorldObjects(){
    for(const t of traffic){const jitter=Math.sin(t.phase)*10;drawCar(t.x+(t.axis==='x'?jitter:0),t.y+(t.axis==='y'?jitter:0),t.axis==='x'?(t.dir>0?0:Math.PI):(t.dir>0?Math.PI/2:-Math.PI/2),t.color)}
    for(const c of parked){if(c.occupied)continue;drawCar(c.x,c.y,c.angle,c.color);}
    // glowing job destination beacon and pulsing ring
    if(step<destinations.length){const d=destinations[step],p=screen(d.x,d.y),pulse=1+Math.sin(performance.now()/220)*.13;if(p.x>-70&&p.x<W+70&&p.y>-70&&p.y<H+70){ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle='rgba(216,255,88,.78)';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,26*pulse,15*pulse,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='rgba(216,255,88,.17)';ctx.beginPath();ctx.arc(0,0,20,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e5ff86';ctx.beginPath();ctx.arc(0,0,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f2f4e9';ctx.font='700 9px DM Sans';ctx.textAlign='center';ctx.fillText(d.label,0,-29);ctx.restore()}}
    const x=inCar?car.x:player.x,y=inCar?car.y:player.y,a=inCar?car.angle:player.angle,p=screen(x,y);
    if(inCar)drawCar(x,y,a,car.color,true);else{ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a);ctx.fillStyle='rgba(20,29,23,.35)';ctx.beginPath();ctx.ellipse(2,5,8,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d8a675';ctx.beginPath();ctx.arc(0,-2,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#263a33';rounded(-4,1,8,10,3);ctx.fillStyle='#e7d4a9';ctx.fillRect(-5,3,3,4);ctx.fillRect(2,3,3,4);ctx.restore()}
  }
  function drawMinimap(){const w=180,h=180;mctx.clearRect(0,0,w,h);mctx.fillStyle='#26332d';mctx.fillRect(0,0,w,h);let sx=w/WORLD.w,sy=h/WORLD.h;
